	1 = NONE — no authentication;
	2 = SIMPLE — simple password authentication;
	3 = HMAC_MD5 — HMAC-MD5 authentication (auth-key-id is only configurable with this type);
	4 = HMAC_SHA_256 — HMAC-SHA-256 authentication.

